import * as React from "react";
import {
  Card,
  type CardProps,
  type CardIntensity,
  type CardSize,
  type CardVariant,
} from "@/components/ui/card";
import { HaloIcon } from "@/components/icons/halo-icon";
import {
  ArrowUp01Icon,
  ArrowDown01Icon,
  MinusSignIcon,
} from "@hugeicons/core-free-icons";
import { cn } from "@/lib/utils";

/* -------------------------------------------------------------------------
 * TYPES & MODELS
 * ----------------------------------------------------------------------- */

export type StatTrendDirection = "up" | "down" | "neutral";
export type StatTrendSentiment = "positive" | "negative" | "neutral";

export interface StatCardProps extends CardProps {
  // Reuses all Card composition infrastructure
}

/* -------------------------------------------------------------------------
 * 1. ROOT STAT CARD COMPONENT
 * Single metric summary built directly on Card architecture.
 * Server-Component compatible with zero client-side JavaScript overhead.
 * ----------------------------------------------------------------------- */

export function StatCard({
  className,
  size = "default",
  intensity = "subtle",
  variant = "default",
  interactive = false,
  ...props
}: StatCardProps) {
  return (
    <Card
      data-slot="stat-card"
      size={size}
      intensity={intensity}
      variant={variant}
      interactive={interactive}
      className={cn("group/stat-card min-w-0 justify-between", className)}
      {...props}
    />
  );
}

/* -------------------------------------------------------------------------
 * 2. STAT CARD HEADER
 * Structural row arranging the metric label and optional category icon or action.
 * ----------------------------------------------------------------------- */

export interface StatCardHeaderProps extends React.ComponentProps<"div"> {}

export function StatCardHeader({ className, ...props }: StatCardHeaderProps) {
  return (
    <div
      data-slot="stat-card-header"
      className={cn(
        "flex items-center justify-between gap-2 px-(--card-spacing) min-w-0",
        className
      )}
      {...props}
    />
  );
}

/* -------------------------------------------------------------------------
 * 3. STAT CARD LABEL
 * Concise metric label explaining what the measurable value represents.
 * ----------------------------------------------------------------------- */

export interface StatCardLabelProps extends React.ComponentProps<"div"> {
  asChild?: boolean;
  as?: "span" | "h2" | "h3" | "h4" | "h5" | "h6" | "div";
}

export function StatCardLabel({
  className,
  asChild = false,
  as = "span",
  ...props
}: StatCardLabelProps) {
  const Comp = as as any;

  return (
    <Comp
      data-slot="stat-card-label"
      className={cn(
        "text-xs sm:text-sm font-medium text-muted-foreground truncate select-none leading-normal",
        "group-data-[size=sm]/card:text-xs",
        "group-data-[size=lg]/card:text-base",
        className
      )}
      {...props}
    />
  );
}

/* -------------------------------------------------------------------------
 * 4. STAT CARD ICON
 * Category indicator container with restrained material styling.
 * Prohibits distracting glowing glass orbs in dense dashboard interfaces.
 * ----------------------------------------------------------------------- */

export interface StatCardIconProps extends React.ComponentProps<"div"> {}

export function StatCardIcon({ className, ...props }: StatCardIconProps) {
  return (
    <div
      data-slot="stat-card-icon"
      className={cn(
        "flex size-7 sm:size-8 items-center justify-center rounded-lg bg-muted/40 text-muted-foreground shrink-0 border border-border/40",
        "group-data-[size=sm]/card:size-6 sm:group-data-[size=sm]/card:size-7",
        "group-data-[size=lg]/card:size-9 sm:group-data-[size=lg]/card:size-10",
        className
      )}
      {...props}
    />
  );
}

/* -------------------------------------------------------------------------
 * 5. STAT CARD ACTION
 * Optional action or menu slot positioned in the header.
 * ----------------------------------------------------------------------- */

export interface StatCardActionProps extends React.ComponentProps<"div"> {}

export function StatCardAction({ className, ...props }: StatCardActionProps) {
  return (
    <div
      data-slot="stat-card-action"
      className={cn("flex items-center gap-1 shrink-0 -mr-1", className)}
      {...props}
    />
  );
}

/* -------------------------------------------------------------------------
 * 6. STAT CARD VALUE
 * The dominant visual quantitative metric.
 * Strictly supports numbers, strings, formatted currency, durations, and zero.
 * NOTE: Never coerces 0 to falsy.
 * ----------------------------------------------------------------------- */

export interface StatCardValueProps extends React.ComponentProps<"div"> {}

export function StatCardValue({
  className,
  children,
  ...props
}: StatCardValueProps) {
  return (
    <div
      data-slot="stat-card-value"
      className={cn(
        "px-(--card-spacing) font-heading text-2xl sm:text-3xl font-bold tracking-tight text-foreground tabular-nums min-w-0 truncate leading-none",
        "group-data-[size=sm]/card:text-xl sm:group-data-[size=sm]/card:text-2xl",
        "group-data-[size=lg]/card:text-3xl sm:group-data-[size=lg]/card:text-4xl",
        className
      )}
      {...props}
    >
      {children}
    </div>
  );
}

/* -------------------------------------------------------------------------
 * 7. STAT CARD FOOTER
 * Supporting region for delta trends, baseline periods, and comparisons.
 * ----------------------------------------------------------------------- */

export interface StatCardFooterProps extends React.ComponentProps<"div"> {}

export function StatCardFooter({ className, ...props }: StatCardFooterProps) {
  return (
    <div
      data-slot="stat-card-footer"
      className={cn(
        "flex flex-wrap items-center gap-1.5 px-(--card-spacing) text-xs text-muted-foreground min-w-0 leading-normal",
        "group-data-[size=sm]/card:text-[11px]",
        className
      )}
      {...props}
    />
  );
}

/* -------------------------------------------------------------------------
 * 8. STAT CARD TREND
 * Directional and sentiment indicator.
 * CRITICAL ARCHITECTURAL MANDATE: DIRECTION != SENTIMENT
 * Lower latency is good (down = positive). Lower revenue is bad (down = negative).
 * Direction and sentiment are deliberately decoupled.
 * ----------------------------------------------------------------------- */

export interface StatCardTrendProps extends React.ComponentProps<"span"> {
  /**
   * Geometric direction of change. Controls the icon arrow.
   * @default "neutral"
   */
  direction?: StatTrendDirection;
  /**
   * Business/semantic desirability of the change. Controls color tokens.
   * @default "neutral"
   */
  sentiment?: StatTrendSentiment;
  /**
   * Accessible description for assistive technology.
   */
  srLabel?: string;
}

export function StatCardTrend({
  direction = "neutral",
  sentiment = "neutral",
  srLabel,
  className,
  children,
  ...props
}: StatCardTrendProps) {
  const IconComponent =
    direction === "up"
      ? ArrowUp01Icon
      : direction === "down"
      ? ArrowDown01Icon
      : MinusSignIcon;

  const defaultSrLabel =
    srLabel ||
    `${sentiment === "positive" ? "Favorable" : sentiment === "negative" ? "Unfavorable" : "Neutral"} trend: ${direction}`;

  return (
    <span
      data-slot="stat-card-trend"
      data-direction={direction}
      data-sentiment={sentiment}
      className={cn(
        "inline-flex items-center gap-1 rounded-md px-1.5 py-0.5 font-medium text-xs tabular-nums border",
        // Semantic Sentiment Color Mapping (Decoupled from arrow direction)
        sentiment === "positive" && [
          "border-emerald-500/25 bg-emerald-500/10 text-emerald-700 dark:text-emerald-400",
        ],
        sentiment === "negative" && [
          "border-rose-500/25 bg-rose-500/10 text-rose-700 dark:text-rose-400",
        ],
        sentiment === "neutral" && [
          "border-border/60 bg-muted/40 text-muted-foreground",
        ],
        className
      )}
      {...props}
    >
      <HaloIcon icon={IconComponent} size={12} className="shrink-0" />
      <span>{children}</span>
      <span className="sr-only">({defaultSrLabel})</span>
    </span>
  );
}

/* -------------------------------------------------------------------------
 * 9. STAT CARD DESCRIPTION
 * Supporting description or baseline comparison text (e.g. "vs last month").
 * ----------------------------------------------------------------------- */

export interface StatCardDescriptionProps extends React.ComponentProps<"span"> {}

export function StatCardDescription({
  className,
  ...props
}: StatCardDescriptionProps) {
  return (
    <span
      data-slot="stat-card-description"
      className={cn("text-muted-foreground truncate", className)}
      {...props}
    />
  );
}

/* -------------------------------------------------------------------------
 * COMPOUND & SUBCOMPONENT EXPORTS
 * ----------------------------------------------------------------------- */

StatCard.Header = StatCardHeader;
StatCard.Label = StatCardLabel;
StatCard.Icon = StatCardIcon;
StatCard.Action = StatCardAction;
StatCard.Value = StatCardValue;
StatCard.Footer = StatCardFooter;
StatCard.Trend = StatCardTrend;
StatCard.Description = StatCardDescription;

export {
  StatCard as Root,
  StatCardHeader as Header,
  StatCardLabel as Label,
  StatCardIcon as Icon,
  StatCardAction as Action,
  StatCardValue as Value,
  StatCardFooter as Footer,
  StatCardTrend as Trend,
  StatCardDescription as Description,
};

@import "./halo-material.css";

/**
 * HaloUI Liquid Material Design System Tokens
 * Physical optical material engine: refraction, specular highlight, optical edges,
 * neoskeuomorphic depth, tactile compression, and virtual directional lighting.
 */

:root {
  /* Surfaces (Flat & Structural) */
  --halo-surface: #ffffff;
  --halo-surface-muted: #f4f5f7;
  --halo-surface-elevated: #ffffff;
  --halo-surface-inset: #f8f9fb;
  --halo-surface-recessed: #f1f2f5;

  /* Borders */
  --halo-border: #d2d6dc;
  --halo-border-subtle: #e5e7eb;
  --halo-border-strong: #9ca3af;

  /* Tactile Controls: Neutral / Default */
  --halo-control-top: #ffffff;
  --halo-control-bottom: #f3f4f6;
  --halo-control-border: #d1d5db;
  --halo-control-depth: #cbd1d8;
  --halo-control-highlight: rgba(255, 255, 255, 0.9);
  --halo-control-text: #111827;

  /* Primary Action (Neutral Monochrome Tactile) */
  --halo-primary-top: #18191d;
  --halo-primary-bottom: #0f1013;
  --halo-primary-border: #23252a;
  --halo-primary-depth: #050507;
  --halo-primary-highlight: rgba(255, 255, 255, 0.22);
  --halo-primary-foreground: #ffffff;
  --halo-primary-hover-top: #24262c;
  --halo-primary-hover-bottom: #14161a;

  /* Secondary Action */
  --halo-secondary-top: #ffffff;
  --halo-secondary-bottom: #f4f5f7;
  --halo-secondary-border: #d1d5db;
  --halo-secondary-depth: #cbd1d8;
  --halo-secondary-highlight: rgba(255, 255, 255, 0.85);
  --halo-secondary-foreground: #1f2937;

  /* Destructive Action */
  --halo-destructive-top: #e53935;
  --halo-destructive-bottom: #d32f2f;
  --halo-destructive-border: #b71c1c;
  --halo-destructive-depth: #8b0000;
  --halo-destructive-highlight: rgba(255, 255, 255, 0.28);
  --halo-destructive-foreground: #ffffff;

  /* Inset Inputs & Wells */
  --halo-input-background: #ffffff;
  --halo-input-border: #d1d5db;
  --halo-input-shadow: inset 0 1px 2px rgba(0, 0, 0, 0.08);

  /* Elevated Overlays & Pop Cards (Apple iOS / macOS frosted liquid glass with high legibility - not too transparent) */
  --halo-elevated-background: rgba(255, 255, 255, 0.92);
  --halo-elevated-border: rgba(255, 255, 255, 0.85);
  --halo-elevated-shadow: inset 0 1px 1px 0 rgba(255, 255, 255, 0.95), inset 0 -1px 1px 0 rgba(0, 0, 0, 0.04), 0 16px 40px -4px rgba(0, 0, 0, 0.10), 0 4px 12px rgba(0, 0, 0, 0.04);
  --halo-glass-pop-background: rgba(255, 255, 255, 0.92);
  --halo-glass-pop-border: rgba(255, 255, 255, 0.85);
  --halo-glass-pop-blur: 20px;
  --halo-glass-pop-shadow: inset 0 1px 1px 0 rgba(255, 255, 255, 0.95), inset 0 -1px 1px 0 rgba(0, 0, 0, 0.04), 0 16px 40px -4px rgba(0, 0, 0, 0.10), 0 4px 12px rgba(0, 0, 0, 0.04);

  /* Corner Radii */
  --halo-radius-xs: 6px;
  --halo-radius-sm: 8px;
  --halo-radius-control: 11px;
  --halo-radius-md: 12px;
  --halo-radius-lg: 16px;
  --halo-radius-xl: 20px;
  --halo-radius-full: 9999px;

  /* Focus Ring Tokens (Shared Accessibility Infrastructure) */
  --halo-focus-color: #0284c7;
  --halo-focus-offset: 2px;
  --halo-focus-width: 2px;
  --halo-focus-offset-color: #ffffff;
  --halo-focus-outer-color: rgba(2, 132, 199, 0.25);
  --halo-focus-shadow: 0 0 0 var(--halo-focus-offset) var(--halo-focus-offset-color),
                       0 0 0 calc(var(--halo-focus-offset) + var(--halo-focus-width)) var(--halo-focus-color),
                       0 0 0 calc(var(--halo-focus-offset) + var(--halo-focus-width) + 1.5px) var(--halo-focus-outer-color);

  /* Motion Presets & Timing Architecture */
  --halo-duration-micro: 80ms;
  --halo-duration-press: 80ms;
  --halo-duration-state: 140ms;
  --halo-duration-reveal: 180ms;
  --halo-duration-settle: 240ms;
  --halo-ease-tactile: cubic-bezier(0.2, 0.8, 0.3, 1);
  --halo-ease-spring: cubic-bezier(0.16, 1, 0.3, 1);
  --halo-ease-out: cubic-bezier(0, 0, 0.2, 1);

  /* Typography & Canvas */
  --halo-canvas: #fbfbfd;
  --halo-canvas-card: #f5f5f7;
  --halo-canvas-subtle: #eaecee;
  --halo-text-primary: #121316;
  --halo-text-secondary: #585c65;
  --halo-text-tertiary: #8b909c;

  /* Backward Compatibility Bridges */
  --halo-edge: rgba(0, 0, 0, 0.1);
  --halo-edge-soft: rgba(0, 0, 0, 0.05);
  --halo-edge-bright: rgba(255, 255, 255, 0.9);
  --halo-edge-inner: inset 0 1px 0 rgba(255, 255, 255, 0.85);
  --halo-edge-outer: 0 0 0 1px rgba(0, 0, 0, 0.08);
  --halo-highlight: linear-gradient(180deg, rgba(255, 255, 255, 0.35) 0%, rgba(255, 255, 255, 0) 100%);
  --halo-highlight-strength: 0.85;
  --halo-shadow-contact: 0 1px 2px rgba(0, 0, 0, 0.06);
  --halo-shadow-elevated: 0 1px 2px rgba(0, 0, 0, 0.06), 0 8px 24px rgba(0, 0, 0, 0.08);
  --halo-shadow-ambient: 0 12px 28px rgba(0, 0, 0, 0.08);
  --halo-shadow-compressed: inset 0 1px 2px rgba(0, 0, 0, 0.12);
  --halo-blur-sm: 0px;
  --halo-blur-md: 0px;
  --halo-blur-lg: 0px;
  --halo-blur-xl: 0px;
  --halo-refraction-strength: 0;
  --halo-refraction-offset: 0;
  --halo-noise-opacity: 0;
  --halo-glow: transparent;
}

.dark {
  /* Surfaces (Dark Mode: Solid graphite/slate) */
  --halo-surface: #14161a;
  --halo-surface-muted: #1c1e24;
  --halo-surface-elevated: #1e2027;
  --halo-surface-inset: #0e0f13;
  --halo-surface-recessed: #181920;

  /* Borders */
  --halo-border: #30343f;
  --halo-border-subtle: #252831;
  --halo-border-strong: #4a5061;

  /* Tactile Controls: Neutral / Default */
  --halo-control-top: #262930;
  --halo-control-bottom: #1c1e24;
  --halo-control-border: #383c46;
  --halo-control-depth: #111317;
  --halo-control-highlight: rgba(255, 255, 255, 0.14);
  --halo-control-text: #f3f4f6;

  /* Primary Action (High-Contrast White in Dark Mode) */
  --halo-primary-top: #ffffff;
  --halo-primary-bottom: #f1f2f4;
  --halo-primary-border: #e2e4e9;
  --halo-primary-depth: #c4c8d0;
  --halo-primary-highlight: rgba(255, 255, 255, 1);
  --halo-primary-foreground: #0f1013;
  --halo-primary-hover-top: #ffffff;
  --halo-primary-hover-bottom: #e5e7eb;

  /* Secondary Action */
  --halo-secondary-top: #262930;
  --halo-secondary-bottom: #1c1e24;
  --halo-secondary-border: #383c46;
  --halo-secondary-depth: #111317;
  --halo-secondary-highlight: rgba(255, 255, 255, 0.14);
  --halo-secondary-foreground: #f3f4f6;

  /* Destructive Action */
  --halo-destructive-top: #dc2626;
  --halo-destructive-bottom: #b91c1c;
  --halo-destructive-border: #991b1b;
  --halo-destructive-depth: #450a0a;
  --halo-destructive-highlight: rgba(255, 255, 255, 0.22);
  --halo-destructive-foreground: #ffffff;

  /* Inset Inputs & Wells */
  --halo-input-background: #0e0f13;
  --halo-input-border: #30343f;
  --halo-input-shadow: inset 0 1px 2px rgba(0, 0, 0, 0.4);

  /* Elevated Overlays & Pop Cards (Apple iOS / macOS frosted liquid glass with high legibility - not too transparent) */
  --halo-elevated-background: rgba(22, 24, 30, 0.92);
  --halo-elevated-border: rgba(255, 255, 255, 0.15);
  --halo-elevated-shadow: inset 0 1px 1px 0 rgba(255, 255, 255, 0.22), inset 0 -1px 1px 0 rgba(0, 0, 0, 0.70), 0 20px 48px -6px rgba(0, 0, 0, 0.65), 0 6px 16px rgba(0, 0, 0, 0.50);
  --halo-glass-pop-background: rgba(22, 24, 30, 0.92);
  --halo-glass-pop-border: rgba(255, 255, 255, 0.15);
  --halo-glass-pop-blur: 20px;
  --halo-glass-pop-shadow: inset 0 1px 1px 0 rgba(255, 255, 255, 0.22), inset 0 -1px 1px 0 rgba(0, 0, 0, 0.70), 0 20px 48px -6px rgba(0, 0, 0, 0.65), 0 6px 16px rgba(0, 0, 0, 0.50);

  /* Focus Ring Tokens */
  --halo-focus-color: #38bdf8;
  --halo-focus-offset: 2px;
  --halo-focus-width: 2px;
  --halo-focus-offset-color: #0c0d0f;
  --halo-focus-outer-color: rgba(56, 189, 248, 0.35);
  --halo-focus-shadow: 0 0 0 var(--halo-focus-offset) var(--halo-focus-offset-color),
                       0 0 0 calc(var(--halo-focus-offset) + var(--halo-focus-width)) var(--halo-focus-color),
                       0 0 0 calc(var(--halo-focus-offset) + var(--halo-focus-width) + 1.5px) var(--halo-focus-outer-color);

  /* Typography & Canvas */
  --halo-canvas: #0c0d0f;
  --halo-canvas-card: #141518;
  --halo-canvas-subtle: #1c1e22;
  --halo-text-primary: #f6f7f9;
  --halo-text-secondary: #9ea3ae;
  --halo-text-tertiary: #656a76;

  /* Backward Compatibility Bridges */
  --halo-edge: rgba(255, 255, 255, 0.12);
  --halo-edge-soft: rgba(255, 255, 255, 0.05);
  --halo-edge-bright: rgba(255, 255, 255, 0.22);
  --halo-edge-inner: inset 0 1px 0 rgba(255, 255, 255, 0.14);
  --halo-edge-outer: 0 0 0 1px rgba(255, 255, 255, 0.08);
  --halo-highlight: linear-gradient(180deg, rgba(255, 255, 255, 0.12) 0%, rgba(255, 255, 255, 0) 100%);
  --halo-highlight-strength: 0.55;
  --halo-shadow-contact: 0 1px 2px rgba(0, 0, 0, 0.4);
  --halo-shadow-elevated: 0 1px 2px rgba(0, 0, 0, 0.4), 0 8px 24px rgba(0, 0, 0, 0.55);
  --halo-shadow-ambient: 0 16px 36px rgba(0, 0, 0, 0.6);
  --halo-shadow-compressed: inset 0 1px 2px rgba(0, 0, 0, 0.5);
  --halo-blur-sm: 0px;
  --halo-blur-md: 0px;
  --halo-blur-lg: 0px;
  --halo-blur-xl: 0px;
  --halo-refraction-strength: 0;
  --halo-refraction-offset: 0;
  --halo-noise-opacity: 0;
  --halo-glow: transparent;
}

/* Explicit Stage Scopes for Interactive Previews */
.light,
[data-stage-theme="light"] {
  --halo-surface: #ffffff;
  --halo-surface-muted: #f4f5f7;
  --halo-surface-elevated: #ffffff;
  --halo-surface-inset: #f8f9fb;
  --halo-surface-recessed: #f1f2f5;

  --halo-border: #d2d6dc;
  --halo-border-subtle: #e5e7eb;
  --halo-border-strong: #9ca3af;

  --halo-control-top: #ffffff;
  --halo-control-bottom: #f3f4f6;
  --halo-control-border: #d1d5db;
  --halo-control-depth: #cbd1d8;
  --halo-control-highlight: rgba(255, 255, 255, 0.9);
  --halo-control-text: #111827;

  --halo-primary-top: #18191d;
  --halo-primary-bottom: #0f1013;
  --halo-primary-border: #23252a;
  --halo-primary-depth: #050507;
  --halo-primary-highlight: rgba(255, 255, 255, 0.22);
  --halo-primary-foreground: #ffffff;
  --halo-primary-hover-top: #24262c;
  --halo-primary-hover-bottom: #14161a;

  --halo-secondary-top: #ffffff;
  --halo-secondary-bottom: #f4f5f7;
  --halo-secondary-border: #d1d5db;
  --halo-secondary-depth: #cbd1d8;
  --halo-secondary-highlight: rgba(255, 255, 255, 0.85);
  --halo-secondary-foreground: #1f2937;

  --halo-destructive-top: #e53935;
  --halo-destructive-bottom: #d32f2f;
  --halo-destructive-border: #b71c1c;
  --halo-destructive-depth: #8b0000;
  --halo-destructive-highlight: rgba(255, 255, 255, 0.28);
  --halo-destructive-foreground: #ffffff;

  --halo-input-background: #ffffff;
  --halo-input-border: #d1d5db;
  --halo-input-shadow: inset 0 1px 2px rgba(0, 0, 0, 0.08);

  --halo-elevated-background: rgba(255, 255, 255, 0.92);
  --halo-elevated-border: rgba(255, 255, 255, 0.85);
  --halo-elevated-shadow: inset 0 1px 1px 0 rgba(255, 255, 255, 0.95), inset 0 -1px 1px 0 rgba(0, 0, 0, 0.04), 0 16px 40px -4px rgba(0, 0, 0, 0.10), 0 4px 12px rgba(0, 0, 0, 0.04);
  --halo-glass-pop-background: rgba(255, 255, 255, 0.92);
  --halo-glass-pop-border: rgba(255, 255, 255, 0.85);
  --halo-glass-pop-blur: 20px;
  --halo-glass-pop-shadow: inset 0 1px 1px 0 rgba(255, 255, 255, 0.95), inset 0 -1px 1px 0 rgba(0, 0, 0, 0.04), 0 16px 40px -4px rgba(0, 0, 0, 0.10), 0 4px 12px rgba(0, 0, 0, 0.04);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.145 0 0);

  --halo-focus-color: #0284c7;
  --halo-focus-offset-color: #ffffff;
  --halo-focus-outer-color: rgba(2, 132, 199, 0.25);

  --halo-canvas: #fbfbfd;
  --halo-canvas-card: #f5f5f7;
  --halo-canvas-subtle: #eaecee;
  --halo-text-primary: #121316;
  --halo-text-secondary: #585c65;
  --halo-text-tertiary: #8b909c;

  /* Scoped semantic background / foreground for light stage */
  --background: oklch(1 0 0);
  --foreground: oklch(0.145 0 0);
  --primary: oklch(0.205 0 0);
  --primary-foreground: oklch(0.985 0 0);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.145 0 0);
