/* ---------------------------------------------------------
   04. DEMO ENVIRONMENT
   --------------------------------------------------------- */

.halo-liquid-environment {
  min-height: 100vh;
  display: grid;
  place-items: center;
  background: var(--halo-page-background);
}

/* ---------------------------------------------------------
   05. ORIGINAL FX LAYER
   --------------------------------------------------------- */

.halo-fx-layer {
  filter: contrast(3);
}

/* =========================================================
   06. CORE LIQUID GLASS SURFACE
   ========================================================= */

.halo-liquid-glass,
.halo-material {
  --halo-glass-width: 100px;
  --halo-glass-height: 100px;
  --halo-glass-radius: 9999px;
  --halo-glass-transition: 25%;

  position: relative;
  z-index: 1;

  border-radius: var(--halo-glass-radius);

  border:
    1px double
    var(--halo-glass-border);

  background:
    var(--halo-glass-background);

  backdrop-filter:
    blur(var(--halo-glass-blur, 10px)) saturate(180%);

  -webkit-backdrop-filter:
    blur(var(--halo-glass-blur, 10px)) saturate(180%);

  box-shadow:
    inset 0 1px 1.5px 0
      var(--halo-glass-inner-highlight-strong),

    inset 0 0 0 1px
      var(--halo-glass-inner-highlight),

    inset 0 -1px 1px 0
      var(--halo-glass-inner-dark),

    0 4px 14px -2px
      var(--halo-glass-shadow);

  cursor: pointer;

  filter: none;

  user-select: none;

  isolation: isolate;

  transition:
    transform 250ms ease,
    background-color 250ms ease,
    box-shadow 250ms ease,
    filter 200ms ease;
}

:is(.dark, html[data-theme="dark"], [data-stage-theme="dark"]) :is(.halo-liquid-glass, .halo-material) {
  filter: none;
}

/* =========================================================
   08. INTERNAL REFRACTION / OPTICAL MENISCUS EDGE
   Equivalent to the approved .box::before for circular showcase
   and geometry-adapted for controls.
   ========================================================= */

.halo-liquid-glass::before,
.halo-material::before {
  content: "";

  position: absolute;

  z-index: 1;

  top: 35%;
  left: 50%;

  transform:
    translateX(-50%);

  width:
    calc(100% - 16px);

  height:
    calc(100% - 16px);

  border-radius:
    inherit;

  border:
    1px solid
    var(--halo-glass-refraction-edge);

  filter:
    blur(6px);

  pointer-events:
    none;
}

/* Hide blurred circle refraction edge on rectangular controls to prevent dark haze or patches */
:where(.halo-liquid-glass, .halo-material):is([data-size="sm"], [data-size="default"], [data-size="lg"], button, [role="button"], input, .h-8, .h-9, .h-10, .h-11, .h-12):not([data-size="showcase"]):not(.size-\[100px\])::before {
  display: none;
}

/* =========================================================
   09. OPTICAL HIGHLIGHT / NATURAL GLASS SPECULAR REFLECTION
   Natural top-down physical light reflection (overhead light).
   Zero diagonal corner blobs, pure liquid crystal sheen.
   ========================================================= */

.halo-liquid-glass::after,
.halo-material::after {
  content: "";

  position: absolute;

  z-index: 2;

  inset: 0;

  border-radius:
    inherit;

  background:
    linear-gradient(
      180deg,
      rgba(255, 255, 255, 0.28) 0%,
      rgba(255, 255, 255, 0.04) 40%,
      transparent 65%
    );

  pointer-events:
    none;
}

:is(.dark, html[data-theme="dark"], [data-stage-theme="dark"]) :is(.halo-liquid-glass, .halo-material)::after {
  background:
    linear-gradient(
      180deg,
      rgba(255, 255, 255, 0.14) 0%,
      rgba(255, 255, 255, 0.02) 35%,
      transparent 60%
    );
}

/* For 100x100 showcase circular lens only: preserve diagonal optical reflection */
.halo-liquid-glass:is([data-size="showcase"], .size-\[100px\])::after,
.halo-material:is([data-size="showcase"], .size-\[100px\])::after {
  background:
    linear-gradient(
      45deg,
      var(--halo-glass-optical-highlight) 0%,
      transparent var(--halo-glass-transition, 25%),
      transparent calc(100% - var(--halo-glass-transition, 25%)),
      var(--halo-glass-optical-highlight) 100%
    );
  filter: blur(7px);
}

/* =========================================================
   10. INNER OVERLAY / OPTICAL BORDER
   Equivalent to .circle-overlay
   ========================================================= */

.halo-liquid-overlay,
.circle-overlay {
  position: absolute;

  z-index: 2;

  inset: 4.5px;

  border:
    1px solid
    var(--halo-glass-overlay-border);

  border-radius:
    inherit;

  filter:
    blur(1px);

  pointer-events:
    none;
}

/* =========================================================
   11. CONTENT LAYER
   Critical: content must remain above decorative optics.
   ========================================================= */

.halo-liquid-content,
.halo-liquid-glass > :not(.halo-liquid-overlay):not(.circle-overlay),
.halo-material > :not(.halo-liquid-overlay):not(.circle-overlay) {
  position: relative;
  z-index: 3;
}

.halo-liquid-icon {
  position: relative;
  z-index: 3;
  width: 28px;
  color: var(--halo-glass-text);
  fill: currentColor;
  filter: drop-shadow(0 25px 3px var(--halo-glass-icon-shadow));
}

.halo-liquid-text {
  position: relative;
  z-index: 3;
  color: var(--halo-glass-text);
  filter: drop-shadow(0 25px 3px var(--halo-glass-text-shadow));
}

/* =========================================================
   12. CANONICAL REFERENCE .box & .circle-overlay
   Fluid liquid glass reference
   ========================================================= */

.box {
  --w: 100px;
  --h: 100px;
  --r: 9999px;
