    inset -6px 6px 1px -6px rgba(255, 255, 255, 0.22),
    inset 0 0 2px rgba(0, 0, 0, 0.95),
    0 4px 8px rgba(0, 0, 0, 0.55);
}

.box::before {
  content: "";
  position: absolute;
  z-index: 1;
  top: 35%;
  left: 50%;
  transform: translateX(-50%);
  width: calc(var(--w) - 16px);
  height: calc(var(--h) - 16px);
  border-radius: inherit;
  border: 1px solid rgba(0, 0, 0, 0.9);
  filter: blur(8px);
  pointer-events: none;
}

:is(.dark, html[data-theme="dark"], [data-stage-theme="dark"]) .box::before {
  border-color: rgba(0, 0, 0, 0.95);
}

.box::after {
  content: "";
  position: absolute;
  z-index: 2;
  inset: 0;
  border-radius: inherit;
  filter: blur(7px);
  background: linear-gradient(
    45deg,
    rgba(255, 255, 255, 0.8) 0%,
    transparent var(--tr),
    transparent calc(100% - var(--tr)),
    rgba(255, 255, 255, 0.8) 100%
  );
  pointer-events: none;
}

:is(.dark, html[data-theme="dark"], [data-stage-theme="dark"]) .box::after {
  background: linear-gradient(
    45deg,
    rgba(255, 255, 255, 0.42) 0%,
    transparent var(--tr),
    transparent calc(100% - var(--tr)),
    rgba(255, 255, 255, 0.42) 100%
  );
}

/* =========================================================
   13. LIQUID GLASS BUTTON
   ========================================================= */

.halo-liquid-button {
  padding: 0 0.8rem;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1rem;
  transition: transform 250ms ease, background-color 250ms ease;
}

.halo-liquid-button .halo-liquid-text {
  font-size: 25px;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  color: var(--halo-glass-text);
}

.halo-liquid-button-icon {
  position: relative;
  z-index: 3;
  width: 40px;
  height: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
  background: var(--halo-glass-action);
  border-radius: 50%;
  box-shadow: 0 0 6px rgba(0, 0, 0, 0.3);
  transition: transform 250ms ease;
}

.halo-liquid-button-icon .halo-liquid-icon {
  width: 16px;
  color: var(--halo-glass-action-foreground);
  fill: currentColor;
}

/* Hover & Active Press */
.halo-liquid-button:hover,
.halo-liquid-glass:where(button, a, [role="button"]):hover {
  transform: translateY(-2px);
  filter: brightness(1.06);
  box-shadow:
    inset 0 1px 2px 0 var(--halo-glass-inner-highlight-strong),
    inset 0 0 0 1px var(--halo-glass-inner-highlight),
    inset 0 -1px 1px 0 var(--halo-glass-inner-dark),
    0 8px 24px -4px var(--halo-glass-shadow);
}

.halo-liquid-button:hover .halo-liquid-button-icon {
  transform: scale(1.1);
}

.halo-liquid-button:active,
.halo-liquid-glass:where(button, a, [role="button"]):active {
  transform: scale(0.94);
}

.halo-liquid-button:active .halo-liquid-text {
  color: var(--halo-glass-text-active);
}

.halo-liquid-button:active .halo-liquid-button-icon {
  transform: scale(0.94);
}

/* =========================================================
   14. FLOATING OVERLAYS & POP CARDS (Not too transparent)
   ========================================================= */

.halo-liquid-glass-surface,
.halo-elevated-surface,
.halo-pop-surface {
  z-index: 50;
  isolation: isolate;
  border: 1px solid var(--halo-glass-pop-border);
  background: var(--halo-glass-pop-background);
  backdrop-filter: blur(var(--halo-glass-pop-blur, 20px)) saturate(190%);
  -webkit-backdrop-filter: blur(var(--halo-glass-pop-blur, 20px)) saturate(190%);
  box-shadow: var(--halo-glass-pop-shadow);
}

:where(.halo-liquid-glass-surface, .halo-elevated-surface, .halo-pop-surface) {
  position: relative;
  border-radius: var(--halo-radius-control, 14px);
  transition: opacity 150ms ease, transform 150ms ease;
}

.halo-liquid-glass-surface::before,
.halo-elevated-surface::before,
.halo-pop-surface::before {
  content: "";
  position: absolute;
  z-index: 1;
  inset: 1px;
  border-radius: inherit;
  border: 1px solid rgba(255, 255, 255, 0.40);
  pointer-events: none;
}

:is(.dark, html[data-theme="dark"], [data-stage-theme="dark"]) :is(.halo-liquid-glass-surface, .halo-elevated-surface, .halo-pop-surface)::before {
  border-color: rgba(255, 255, 255, 0.08);
}

.halo-liquid-glass-surface::after,
.halo-elevated-surface::after,
.halo-pop-surface::after {
  content: "";
  position: absolute;
  z-index: 2;
  inset: 0;
  border-radius: inherit;
  background: linear-gradient(
    180deg,
    rgba(255, 255, 255, 0.24) 0%,
    rgba(255, 255, 255, 0.04) 30%,
    transparent 60%
  );
  pointer-events: none;
}

:is(.dark, html[data-theme="dark"], [data-stage-theme="dark"]) :is(.halo-liquid-glass-surface, .halo-elevated-surface, .halo-pop-surface)::after {
  background: linear-gradient(
    180deg,
    rgba(255, 255, 255, 0.12) 0%,
    rgba(255, 255, 255, 0.02) 25%,
    transparent 50%
  );
}

.halo-liquid-glass-surface > *,
.halo-elevated-surface > *,
.halo-pop-surface > * {
  position: relative;
  z-index: 3;
}

/* =========================================================
   15. ACCESSIBLE FOCUS
   ========================================================= */

.halo-liquid-glass:focus-visible,
.halo-focus-ring:focus-visible {
  outline: 3px solid color-mix(in srgb, var(--halo-glass-text) 72%, transparent) !important;
  outline-offset: 4px !important;
  z-index: 10;
}

/* =========================================================
   16. DISABLED
   ========================================================= */

.halo-liquid-glass:disabled,
.halo-liquid-glass[aria-disabled="true"] {
  cursor: not-allowed;
  opacity: 0.58;
  transform: none !important;
}

/* =========================================================
   17. SIZE & GEOMETRY RECIPES
   ========================================================= */

.halo-liquid-glass[data-size="sm"] {
  --halo-glass-width: 72px;
  --halo-glass-height: 72px;
}

.halo-liquid-glass[data-size="md"] {
  --halo-glass-width: 100px;
  --halo-glass-height: 100px;
}

.halo-liquid-glass[data-size="lg"] {
  --halo-glass-width: 124px;
  --halo-glass-height: 124px;
}

.halo-liquid-glass[data-shape="pill"] {
  --halo-glass-radius: 9999px;
  width: auto;
  min-width: var(--halo-glass-width, 72px);
}

.halo-liquid-glass[data-shape="rounded"] {
  --halo-glass-radius: 24px;
}

.halo-liquid-glass[data-shape="circle"] {
  --halo-glass-radius: 9999px;
}

/* =========================================================
   18. REDUCED MOTION
   ========================================================= */

@media (prefers-reduced-motion: reduce) {
  .halo-liquid-button,
  .halo-liquid-button-icon,
  .halo-liquid-glass,
  .halo-material,
  .box {
    transition: none !important;
    animation: none !important;
    transform: none !important;
  }

  .halo-liquid-button:hover,
  .halo-liquid-button:active,
  .halo-liquid-glass:hover,
  .halo-liquid-glass:active,
  .box:hover,
  .box:active {
    transform: none !important;
  }

  .halo-liquid-button:hover .halo-liquid-button-icon,
  .halo-liquid-button:active .halo-liquid-button-icon {
    transform: none !important;
  }
}

/* =========================================================
   19. REDUCED TRANSPARENCY
   ========================================================= */

@media (prefers-reduced-transparency: reduce) {
  .halo-liquid-glass,
  .halo-material,
  .halo-liquid-glass-surface,
  .halo-elevated-surface,
  .box {
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
    background: rgba(245, 245, 247, 0.94) !important;
  }

  .dark .halo-liquid-glass,
  .dark .halo-material,
  .dark .halo-liquid-glass-surface,
  .dark .halo-elevated-surface,
  .dark .box,
  [data-stage-theme="dark"] .halo-liquid-glass,
  [data-stage-theme="dark"] .halo-material,
  [data-stage-theme="dark"] .halo-liquid-glass-surface,
  [data-stage-theme="dark"] .halo-elevated-surface,
  [data-stage-theme="dark"] .box {
    background: rgba(32, 33, 38, 0.96) !important;
  }
}

[data-transparency="reduced"] .halo-liquid-glass,
[data-transparency="reduced"] .halo-material,
[data-transparency="reduced"] .halo-liquid-glass-surface,
[data-transparency="reduced"] .halo-elevated-surface,
[data-transparency="reduced"] .box {
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  background: rgba(245, 245, 247, 0.94) !important;
}

.dark [data-transparency="reduced"] .halo-liquid-glass,
.dark [data-transparency="reduced"] .halo-material,
.dark [data-transparency="reduced"] .halo-liquid-glass-surface,
.dark [data-transparency="reduced"] .halo-elevated-surface,
.dark [data-transparency="reduced"] .box,
[data-stage-theme="dark"] [data-transparency="reduced"] .halo-liquid-glass,
[data-stage-theme="dark"] [data-transparency="reduced"] .halo-material,
[data-stage-theme="dark"] [data-transparency="reduced"] .halo-liquid-glass-surface,
[data-stage-theme="dark"] [data-transparency="reduced"] .halo-elevated-surface,
[data-stage-theme="dark"] [data-transparency="reduced"] .box {
  background: rgba(32, 33, 38, 0.96) !important;
}

/* =========================================================
   20. RESPONSIVE SAFETY
   ========================================================= */

@media (max-width: 640px) {
  .halo-liquid-button {
    max-width: calc(100vw - 32px);
  }

  .halo-liquid-text {
    min-width: 0;
  }
}
/* =========================================================
   21. DEEP OPTICAL LIQUID GLASS
   Progressive lensing layer. Content remains isolated above optics.
   ========================================================= */

.halo-optical-glass {
  --halo-optical-x: 50%;
  --halo-optical-y: 35%;
  --halo-optical-nx: 0;
  --halo-optical-ny: 0;
  --halo-optical-scale: 1;
  --halo-optical-depth: 12px;
  --halo-optical-blur: 9px;
  --halo-optical-saturation: 185%;
  --halo-optical-tint: rgba(255, 255, 255, 0.12);
  --halo-optical-edge: rgba(255, 255, 255, 0.72);
  --halo-optical-shadow: rgba(8, 18, 32, 0.22);

  position: relative;
  isolation: isolate;
  overflow: hidden;
  border: 1px solid color-mix(in srgb, var(--halo-optical-edge) 55%, transparent);
  border-radius: var(--halo-radius-floating);
  background:
    radial-gradient(
      120% 160% at var(--halo-optical-x) var(--halo-optical-y),
      rgba(255,255,255,.20) 0%,
      rgba(255,255,255,.07) 28%,
      transparent 56%
    ),
    var(--halo-optical-tint);
  backdrop-filter:
    blur(var(--halo-optical-blur))
    saturate(var(--halo-optical-saturation))
    brightness(1.04);
  -webkit-backdrop-filter:
    blur(var(--halo-optical-blur))
    saturate(var(--halo-optical-saturation))
    brightness(1.04);
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,.62),
    inset 0 -1px 0 rgba(0,0,0,.10),
    0 10px 28px -14px var(--halo-optical-shadow);
  transform:
    perspective(700px)
    rotateX(calc(var(--halo-optical-ny) * -1.1deg))
    rotateY(calc(var(--halo-optical-nx) * 1.1deg))
    scale(var(--halo-optical-scale));
  transform-style: preserve-3d;
  transition:
    transform 420ms cubic-bezier(.2,.85,.2,1.35),
    box-shadow 220ms ease,
    background 220ms ease;
  will-change: transform;
}

.halo-optical-glass[data-shape="capsule"] { border-radius: 9999px; }
.halo-optical-glass[data-shape="circle"] { border-radius: 50%; aspect-ratio: 1; }

.halo-optical-glass[data-material="clear"] {
  --halo-optical-blur: 3px;
  --halo-optical-tint: rgba(255,255,255,.055);
  --halo-optical-saturation: 205%;
}

.halo-optical-glass[data-material="prominent"] {
  --halo-optical-blur: 13px;
  --halo-optical-tint: rgba(255,255,255,.20);
  --halo-optical-saturation: 195%;
}

.halo-optical-glass[data-lens="subtle"] { --halo-optical-depth: 7px; }
.halo-optical-glass[data-lens="rich"] { --halo-optical-depth: 19px; }

.halo-optical-glass__lens,
.halo-optical-glass__meniscus,
.halo-optical-glass__caustic,
.halo-optical-glass__specular {
  position: absolute;
  inset: 0;
  z-index: 0;
  border-radius: inherit;
  pointer-events: none;
}

.halo-optical-glass__lens {
  inset: 3px;
  background:
    radial-gradient(
      90% 130% at var(--halo-optical-x) var(--halo-optical-y),
      rgba(255,255,255,.16),
      transparent 45%
    ),
    radial-gradient(
      130% 100% at calc(50% + var(--halo-optical-nx) * 8%) calc(50% + var(--halo-optical-ny) * 8%),
      transparent 48%,
      rgba(255,255,255,.10) 68%,
      rgba(0,0,0,.07) 100%
    );
  box-shadow:
    inset calc(var(--halo-optical-nx) * -3px)
      calc(var(--halo-optical-ny) * -3px)
      var(--halo-optical-depth) rgba(255,255,255,.12);
  filter: saturate(1.15);
}

.halo-optical-glass__meniscus {
  inset: 1px;
  border: 1px solid rgba(255,255,255,.38);
  box-shadow:
    inset 1px 1px 1px rgba(255,255,255,.56),
    inset -1px -1px 1px rgba(0,0,0,.16),
    inset 0 0 var(--halo-optical-depth) rgba(255,255,255,.09);
  mask-image: linear-gradient(135deg,#000 0 42%,rgba(0,0,0,.22) 61%,#000 100%);
}

.halo-optical-glass__caustic {
  inset: -28%;
  background:
    conic-gradient(
      from 205deg at var(--halo-optical-x) var(--halo-optical-y),
      transparent 0deg,
      rgba(128,220,255,.13) 35deg,
      rgba(255,255,255,.32) 62deg,
      transparent 105deg,
      transparent 270deg,
      rgba(255,190,230,.10) 315deg,
      transparent 360deg
    );
  filter: blur(14px);
  opacity: .75;
  transform:
    translate(
      calc(var(--halo-optical-nx) * 5px),
      calc(var(--halo-optical-ny) * 5px)
    );
  transition: transform 90ms linear;
}

.halo-optical-glass__specular {
  background:
    radial-gradient(
      34% 62% at var(--halo-optical-x) var(--halo-optical-y),
      rgba(255,255,255,.58) 0%,
      rgba(255,255,255,.18) 32%,
      transparent 72%
    );
  mix-blend-mode: screen;
  opacity: .78;
}

.halo-optical-glass__content {
  position: relative;
  z-index: 2;
  height: 100%;
  width: 100%;
}

.halo-optical-glass[data-interactive]:hover {
  --halo-optical-scale: 1.018;
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,.72),
    inset 0 -1px 0 rgba(0,0,0,.12),
    0 16px 36px -16px var(--halo-optical-shadow);
}

.halo-optical-glass[data-pressed] {
  --halo-optical-scale: .965;
  transition-duration: 90ms;
}

:is(.dark, html[data-theme="dark"], [data-stage-theme="dark"]) .halo-optical-glass {
  --halo-optical-tint: rgba(255,255,255,.065);
  --halo-optical-edge: rgba(255,255,255,.34);
  --halo-optical-shadow: rgba(0,0,0,.55);
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,.28),
    inset 0 -1px 0 rgba(0,0,0,.48),
    0 14px 34px -15px var(--halo-optical-shadow);
}

@media (prefers-reduced-motion: reduce) {
  .halo-optical-glass,
  .halo-optical-glass__caustic {
    transform: none !important;
    transition: none !important;
  }
}

@media (prefers-reduced-transparency: reduce) {
  .halo-optical-glass {
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
    background: var(--halo-material-solid) !important;
  }
  .halo-optical-glass__lens,
  .halo-optical-glass__caustic {
    display: none;
  }
}


/* =========================================================
   22. ADAPTIVE APPEARANCE + COORDINATED GLASS
   Mirrors the public Liquid Glass principles: adaptive light/dark
   appearance, shared sampling intent, proximity blending and interaction.
   ========================================================= */
:root,
.light,
html[data-theme="light"],
[data-stage-theme="light"] {
  --halo-optical-surface: rgba(255,255,255,.13);
  --halo-optical-clear: rgba(255,255,255,.045);
  --halo-optical-prominent: rgba(255,255,255,.23);
  --halo-optical-edge-hi: rgba(255,255,255,.88);
  --halo-optical-edge-lo: rgba(14,20,31,.15);
  --halo-optical-specular-color: rgba(255,255,255,.72);
  --halo-optical-contact: rgba(15,23,42,.20);
  --halo-optical-foreground: rgba(18,18,22,.94);
}

.dark,
html[data-theme="dark"],
[data-stage-theme="dark"] {
  --halo-optical-surface: rgba(20,22,29,.22);
  --halo-optical-clear: rgba(255,255,255,.028);
  --halo-optical-prominent: rgba(45,48,60,.34);
  --halo-optical-edge-hi: rgba(255,255,255,.40);
  --halo-optical-edge-lo: rgba(0,0,0,.68);
  --halo-optical-specular-color: rgba(255,255,255,.46);
  --halo-optical-contact: rgba(0,0,0,.64);
  --halo-optical-foreground: rgba(248,249,252,.96);
}

.halo-glass-container {
  --halo-shared-light-x: 50%;
  --halo-shared-light-y: 30%;
  position: relative;
  isolation: isolate;
}

.halo-glass-container .halo-optical-glass {
  --halo-optical-x: var(--halo-shared-light-x);
  --halo-optical-y: var(--halo-shared-light-y);
}

.halo-optical-glass {
  --halo-glass-proximity: 0;
  --halo-optical-tint: var(--halo-optical-surface);
  --halo-optical-edge: var(--halo-optical-edge-hi);
  color: var(--halo-optical-foreground);
  border-color: color-mix(in srgb, var(--halo-optical-edge-hi) 52%, transparent);
  background:
    radial-gradient(
      115% 150% at var(--halo-optical-x) var(--halo-optical-y),
      color-mix(in srgb, var(--halo-optical-edge-hi) 24%, transparent),
      transparent 54%
    ),
    var(--halo-optical-tint);
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, var(--halo-optical-edge-hi) 58%, transparent),
    inset 0 -1px 0 var(--halo-optical-edge-lo),
    0 12px 32px -16px var(--halo-optical-contact);
}

.halo-optical-glass[data-material="clear"] {
  --halo-optical-tint: var(--halo-optical-clear);
}
.halo-optical-glass[data-material="prominent"] {
  --halo-optical-tint: var(--halo-optical-prominent);
}

.halo-optical-glass__bridge {
  position: absolute;
  z-index: 0;
  pointer-events: none;
  inset: calc(var(--halo-glass-proximity) * -10px);
  border-radius: inherit;
  opacity: var(--halo-glass-proximity);
  background: color-mix(
    in srgb,
    var(--halo-optical-tint) calc(68% + var(--halo-glass-proximity) * 20%),
    transparent
  );
  filter: blur(calc(6px + var(--halo-glass-proximity) * 8px));
  transform: scale(calc(1 + var(--halo-glass-proximity) * .045));
  transition:
    opacity 240ms ease,
    inset 360ms cubic-bezier(.2,.8,.2,1),
    transform 360ms cubic-bezier(.2,.9,.2,1.25);
}

.halo-optical-glass__meniscus {
  border-color: color-mix(in srgb, var(--halo-optical-edge-hi) 48%, transparent);
  box-shadow:
    inset 1px 1px 1px color-mix(in srgb, var(--halo-optical-edge-hi) 64%, transparent),
    inset -1px -1px 1px var(--halo-optical-edge-lo),
    inset 0 0 var(--halo-optical-depth)
      color-mix(in srgb, var(--halo-optical-edge-hi) 12%, transparent);
}

.halo-optical-glass__specular {
  background:
    radial-gradient(
      34% 62% at var(--halo-optical-x) var(--halo-optical-y),
      var(--halo-optical-specular-color) 0%,
      color-mix(in srgb, var(--halo-optical-specular-color) 30%, transparent) 32%,
      transparent 72%
    );
}

@media (prefers-color-scheme: dark) {
  html[data-theme="system"] {
    --halo-optical-surface: rgba(20,22,29,.22);
    --halo-optical-clear: rgba(255,255,255,.028);
    --halo-optical-prominent: rgba(45,48,60,.34);
    --halo-optical-edge-hi: rgba(255,255,255,.40);
    --halo-optical-edge-lo: rgba(0,0,0,.68);
    --halo-optical-specular-color: rgba(255,255,255,.46);
    --halo-optical-contact: rgba(0,0,0,.64);
    --halo-optical-foreground: rgba(248,249,252,.96);
  }
}

@media (prefers-contrast: more) {
  .halo-optical-glass {
    border-width: 2px;
    --halo-optical-blur: 12px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .halo-optical-glass__bridge {
    transition: none !important;
    transform: none !important;
  }
}
